package com.adaptivelearning.evaluation.application;import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;
class MasteryPolicyTest {@Test void missingComponentsAreRemovedFromDenominator(){Instant now=Instant.now();var r=MasteryPolicy.calculate(List.of(new MasteryPolicy.Evidence(MasteryPolicy.Component.Q,80,1,now,true)),now);assertThat(r.score()).isEqualTo(80);}@Test void selfAssessmentOnlyHasLowConfidence(){Instant now=Instant.now();var r=MasteryPolicy.calculate(List.of(new MasteryPolicy.Evidence(MasteryPolicy.Component.S,100,.1,now,false)),now);assertThat(r.score()).isEqualTo(100);assertThat(r.confidence()).isLessThanOrEqualTo(.2);assertThat(r.level()).startsWith("TENTATIVE_");}@Test void combinesOnlyExistingComponents(){Instant now=Instant.now();var r=MasteryPolicy.calculate(List.of(new MasteryPolicy.Evidence(MasteryPolicy.Component.Q,80,1,now,true),new MasteryPolicy.Evidence(MasteryPolicy.Component.S,40,.1,now,false)),now);assertThat(r.score()).isCloseTo(73.8,within(.1));}}
